{"path":"/app/mahjong_eval.py","content":"#!/usr/bin/env python3
"""Evaluate 13-tile Mahjong hands for one-tile winning waits.

The script reads hand_*.json files in /app, determines which winning patterns can be
formed by adding one legal tile, and writes result.txt.
"""

from __future__ import annotations

import glob
import json
from collections import Counter
from functools import lru_cache
from pathlib import Path
from typing import Iterable

SUITS = ("D", "B", "C")
SUITED_TILES = [f"{n}{s}" for s in SUITS for n in range(1, 10)]
HONOR_TILES = ["East", "South", "West", "North", "Red", "Green", "White"]
ALL_TILES = SUITED_TILES + HONOR_TILES
TILE_INDEX = {tile: i for i, tile in enumerate(ALL_TILES)}

ORPHAN_TILES = {
    "1D", "9D", "1B", "9B", "1C", "9C",
    "East", "South", "West", "North", "Red", "Green", "White",
}

PATTERN_LABELS = {
    "Seven Pairs": "Winning hand - Seven Pairs",
    "Standard": "Winning hand - Standard",
    "Thirteen Orphans": "Winning hand - Thirteen Orphans",
}
PATTERN_OUTPUT_ORDER = ["Seven Pairs", "Standard", "Thirteen Orphans"]


def counts_from_tiles(tiles: Iterable[str]) -> tuple[int, ...]:
    """Convert tile strings to a 34-length count tuple, validating tile names."""
    counts = [0] * len(ALL_TILES)
    for tile in tiles:
        if tile not in TILE_INDEX:
            raise ValueError(f"Unknown tile: {tile}")
        counts[TILE_INDEX[tile]] += 1
        if counts[TILE_INDEX[tile]] > 4:
            raise ValueError(f"Too many copies of tile: {tile}")
    return tuple(counts)


def is_seven_pairs(counts: tuple[int, ...]) -> bool:
    """Return True if a 14-tile count vector is exactly seven pairs."""
    return sum(counts) == 14 and sum(1 for count in counts if count == 2) == 7


def is_thirteen_orphans(counts: tuple[int, ...]) -> bool:
    """Return True if a 14-tile count vector is thirteen orphans."""
    if sum(counts) != 14:
        return False
    duplicate_found = False
    for tile, idx in TILE_INDEX.items():
        count = counts[idx]
        if tile in ORPHAN_TILES:
            if count == 0:
                return False
            if count == 2:
                if duplicate_found:
                    return False
                duplicate_found = True
            elif count != 1:
                return False
        elif count != 0:
            return False
    return duplicate_found


def is_standard(counts: tuple[int, ...]) -> bool:
    """Return True if counts can be arranged as 4 melds plus 1 pair."""
    if sum(counts) != 14:
        return False

    @lru_cache(maxsize=None)
    def can_form_melds(state: tuple[int, ...]) -> bool:
        try:
            first = next(i for i, count in enumerate(state) if count)
        except StopIteration:
            return True

        state_list = list(state)

        # Pung: three identical tiles.
        if state_list[first] >= 3:
            state_list[first] -= 3
            if can_form_melds(tuple(state_list)):
                return True
            state_list[first] += 3

        # Chow: three consecutive suited tiles in the same suit.
        tile = ALL_TILES[first]
        if len(tile) == 2 and tile[0].isdigit():
            number = int(tile[0])
            suit = tile[1]
            if number <= 7:
                second = TILE_INDEX.get(f"{number + 1}{suit}")
                third = TILE_INDEX.get(f"{number + 2}{suit}")
                if second is not None and third is not None and state_list[second] and state_list[third]:
                    state_list[first] -= 1
                    state_list[second] -= 1
                    state_list[third] -= 1
                    if can_form_melds(tuple(state_list)):
                        return True
        return False

    for pair_idx, count in enumerate(counts):
        if count >= 2:
            remaining = list(counts)
            remaining[pair_idx] -= 2
            if can_form_melds(tuple(remaining)):
                return True
    return False


def winning_patterns_for_14(counts: tuple[int, ...]) -> set[str]:
    """Return winning pattern names satisfied by a complete 14-tile hand."""
    patterns: set[str] = set()
    if is_seven_pairs(counts):
        patterns.add("Seven Pairs")
    if is_standard(counts):
        patterns.add("Standard")
    if is_thirteen_orphans(counts):
        patterns.add("Thirteen Orphans")
    return patterns


def possible_patterns_for_13(tiles: list[str]) -> set[str]:
    """Return all winning patterns achievable after adding one legal tile."""
    if len(tiles) != 13:
        raise ValueError(f"Expected 13 tiles, got {len(tiles)}")
    base_counts = list(counts_from_tiles(tiles))
    patterns: set[str] = set()
    for idx in range(len(ALL_TILES)):
        if base_counts[idx] >= 4:
            continue
        trial = base_counts.copy()
        trial[idx] += 1
        patterns.update(winning_patterns_for_14(tuple(trial)))
    return patterns


def format_patterns(patterns: set[str]) -> str:
    """Format pattern names as the required brace-enclosed quoted set."""
    if not patterns:
        return '{ "Not a winning hand" }'
    labels = [PATTERN_LABELS[name] for name in PATTERN_OUTPUT_ORDER if name in patterns]
    return "{ " + ", ".join(f'"{label}"' for label in labels) + " }"


def process_directory(directory: str | Path = "/app") -> list[str]:
    """Process all hand_*.json files and return formatted result lines."""
    directory = Path(directory)
    lines: list[str] = []
    for path_str in sorted(glob.glob(str(directory / "hand_*.json"))):
        path = Path(path_str)
        with path.open("r", encoding="utf-8") as fh:
            tiles = json.load(fh)
        if not isinstance(tiles, list) or not all(isinstance(tile, str) for tile in tiles):
            raise ValueError(f"{path.name} must contain a JSON array of tile strings")
        patterns = possible_patterns_for_13(tiles)
        lines.append(f"{path.name}: {format_patterns(patterns)}")
    return lines


def main() -> None:
    directory = Path("/app")
    lines = process_directory(directory)
    (directory / "result.txt").write_text("\n".join(lines) + "\n", encoding="utf-8")


if __name__ == "__main__":
    main()
"}

