{"path":"/app/test_mahjong_eval.py","content":"import re
from pathlib import Path

import mahjong_eval as m


EXPECTED_LINES = [
    'hand_001.json: { "Winning hand - Seven Pairs", "Winning hand - Standard" }',
    'hand_002.json: { "Winning hand - Thirteen Orphans" }',
    'hand_003.json: { "Not a winning hand" }',
    'hand_004.json: { "Winning hand - Seven Pairs" }',
    'hand_005.json: { "Winning hand - Seven Pairs", "Winning hand - Standard" }',
    'hand_006.json: { "Winning hand - Standard" }',
    'hand_007.json: { "Winning hand - Seven Pairs", "Winning hand - Standard" }',
    'hand_008.json: { "Winning hand - Seven Pairs" }',
]


def test_process_directory_expected_results():
    assert m.process_directory("/app") == EXPECTED_LINES


def test_result_txt_matches_generated_output():
    m.main()
    assert Path("/app/result.txt").read_text(encoding="utf-8").splitlines() == EXPECTED_LINES


def test_output_line_format():
    allowed = {
        "Winning hand - Seven Pairs",
        "Winning hand - Standard",
        "Winning hand - Thirteen Orphans",
        "Not a winning hand",
    }
    line_re = re.compile(r"^hand_\d{3}\.json: \{ (.+) \}$")
    for line in EXPECTED_LINES:
        match = line_re.match(line)
        assert match, line
        quoted_items = re.findall(r'"([^"]+)"', match.group(1))
        assert quoted_items
        assert set(quoted_items) <= allowed
        if "Not a winning hand" in quoted_items:
            assert quoted_items == ["Not a winning hand"]


def test_complete_hand_pattern_detectors():
    assert m.winning_patterns_for_14(m.counts_from_tiles([
        "1D", "2D", "3D", "4B", "5B", "6B", "7C", "8C", "9C",
        "East", "East", "East", "White", "White",
    ])) == {"Standard"}

    assert m.winning_patterns_for_14(m.counts_from_tiles([
        "1D", "1D", "2D", "2D", "3B", "3B", "4B", "4B",
        "5C", "5C", "6C", "6C", "7C", "7C",
    ])) == {"Seven Pairs"}

    assert m.winning_patterns_for_14(m.counts_from_tiles([
        "1D", "9D", "1B", "9B", "1C", "9C", "East", "South",
        "West", "North", "Red", "Green", "White", "Red",
    ])) == {"Thirteen Orphans"}


def test_wait_patterns_include_overlap_and_none():
    assert m.possible_patterns_for_13([
        "1D", "1D", "2D", "2D", "3D", "3D", "4B", "4B", "5B", "5B", "6B", "6B", "7C",
    ]) == {"Seven Pairs", "Standard"}

    assert m.possible_patterns_for_13([
        "1D", "3D", "5D", "7D", "9D", "2B", "4B", "6B", "8B", "1C", "3C", "5C", "7C",
    ]) == set()
"}

